    bs.push(Bx(u0,v0,u1,v1,z0,z0+1,sh(wd,.7),{foot:0}),                                                  // its bottom
      Bx(u0,v1-t,u1,v1,z0+1,z0+3,cw,{foot:0}),Bx(u0,v1-t,u1,v1,z0+5,z0+7,cw,{foot:0}),Bx(u0,v0,u1,v0+t,z0+1,z0+7,cw,{foot:0}),   // two front slats (a gap between), the back
      Bx(u0,v0+t,u0+t,v1-t,z0+1,z0+7,sh(cw,.95),{foot:0}),Bx(u1-t,v0+t,u1,v1-t,z0+1,z0+7,sh(cw,.95),{foot:0}));                   // the ends
