const OCTB=LBLD[1];
const OCTR={b:OCTB,lv:SQLV.octo,x0:OCTB.x0+T,y0:OCTB.y0+T,x1:OCTB.x1-T,y1:OCTB.y1-T,H:STORY-8,cx:OCTB.x0+5.5,cy:OCTB.y1-2.6,in:[OCTB.x0-T,OCTB.y0-T,OCTB.x1+T,OCTB.y1+T]};
