  const pl=Math.floor((du+14)/5.6), pu=(du+14)-pl*5.6; let c=pu<.6?DGP.oakD:[DGP.oak,DGP.oakL,DGP.oak,DGP.oakL,DGP.oak][pl]||DGP.oak;
  if(hash(Math.floor(du),Math.floor(dz/3),77)<.12)c=sh(c,.86);                                              // the grain
