const dgnHole=(du,dz)=>{ const a=Math.abs(du); if(dz>=5.5||a>=4)return null; if(dz<4.6*Math.sqrt(Math.max(0,1-(a/3.6)**2)))return DGP.dark; return a<4&&dz<5?DGP.lo:null; };
