  const damp=(cvNoise(x/2.4,y/2.4,1613)*2+cvNoise(x/.9,y/.9,1614))/3+(hash(Math.floor(x*24),Math.floor(y*24),1612)-.5)*.06; if(damp<.42)c=sh(c,damp<.34?.78:.89);   // the damp patches: a smooth field's shapes, dithered at their edges (natural depth, owner 15 Oct 2026)
  if(dr<1.6)c=sh(c,.72+dr*.17);                                                                                                      // sunk round the drain
  if(wall<.45){ const n=hash(Math.floor(x*24),Math.floor(y*24),1615); if(n<(.45-wall)*1.4)c=n<.08?DGP.dust:[(c[0]+DGP.dust[0])/2,(c[1]+DGP.dust[1])/2,(c[2]+DGP.dust[2])/2]; }   // the dust along the walls
