  const nx=dir==='l'?1:dir==='r'?-1:0, ny=dir==='b'?1:dir==='f'?-1:0, FL={ph:0}, B=[], I=C.iron, IL=C.ironL;
  const bx=(ax,ay,bx2,by2,z0,z1,c,o)=>({x0:Math.min(ax,bx2),y0:Math.min(ay,by2),x1:Math.max(ax,bx2),y1:Math.max(ay,by2),z0,z1,foot:0,nb:1,c,top:()=>sh(c,1.1),fi:()=>sh(c,.7),fj:()=>sh(c,.86),...o});
  B.push(bx(x-nx*.16-.02,y-ny*.16-.02,x+.02,y+.02,62,64.5,I,{foot:1}));                                                   // the arm out from the wall (foot: the thing's place, though nothing of it is on the floor)
  B.push(bx(x-.05,y-.05,x+.05,y+.05,62,67,IL)); B.push(bx(x-.035,y-.035,x+.035,y+.035,67,69,I));                        // the ring, its collar
